import sys, heapq, itertools
sys.path.insert(0,'/workspace')
from netsim.graph import WeightedGraph

# RingTopo(k=4, n=1) exactly as netsim/topo.py builds it
edges=[]
switches=['s1','s2','s3','s4']; hosts=['h1','h2','h3','h4']
for i in range(1,5):
    edges.append(('h%d'%i,'s%d'%i))
for i in range(4):
    edges.append(('s%d'%(i+1),'s%d'%((i+1)%4+1)))
print('ring edges',edges)

def mkgraph(skip=None):
    g=WeightedGraph()
    for u,v in edges:
        if skip and set((u,v))==set(skip): continue
        g.add_edge(u,v,weight=1)
    return g

def nsw(p): return sum(1 for n in p if n.startswith('s'))

g=mkgraph()
base={}
tot=0
for a,b in itertools.permutations(hosts,2):
    p=g.shortest_path(a,b); base[(a,b)]=p; tot+=nsw(p)
for k in sorted(base): print(k, base[k], nsw(base[k]))
print('BASE ring rules total',tot)

fail=('s1','s2')
def uses(p,a,b): return any({p[i],p[i+1]}=={a,b} for i in range(len(p)-1))
aff=[k for k,p in base.items() if uses(p,*fail)]
g2=mkgraph(skip=fail)
reins=0; new={}
for k in aff:
    p=g2.shortest_path(*k); new[k]=p; reins+=nsw(p)
print('affected pairs',len(aff),aff)
for k in aff: print('  ',k,base[k],'->',new[k], nsw(base[k]),'->',nsw(new[k]))
print('AFFECTED-ONLY reinstalled rules =',reins)
tot2=sum(nsw(g2.shortest_path(a,b)) for a,b in itertools.permutations(hosts,2))
print('FULL-RECOMPUTE total after failure =',tot2)
print('affected old rules removed =',sum(nsw(base[k]) for k in aff))
"
